:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
  --snake: #4ecca3;
  --food: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  color: var(--primary);
}

.score {
  font-size: 1.125rem;
  font-weight: bold;
  color: var(--snake);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #0a0a1a;
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 24px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--primary);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  max-width: 300px;
}

.overlay strong {
  color: var(--snake);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  min-width: 120px;
}

.btn:hover {
  background: #1a4a7a;
  border-color: var(--snake);
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: #0a2a4a;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
  font-weight: bold;
}

.btn.primary:hover {
  background: #c73550;
  border-color: #fff;
}

.btn.primary:active {
  background: #a82a42;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 100px;
    font-size: 0.9375rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, food, direction, nextDirection, score, running, paused, gameOver, loopId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 0, y: 0 };
    nextDirection = { x: 0, y: 0 };
    score = 0;
    running = false;
    paused = true;
    gameOver = false;
    placeFood();
    updateScore();
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function updateScore() {
    scoreEl.textContent = 'Score: ' + score;
  }

  function draw() {
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL, food.y * CELL, CELL, CELL);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3aa88a';
      ctx.fillRect(seg.x * CELL, seg.y * CELL, CELL, CELL);
    });
  }

  function step() {
    if (!running || paused || gameOver) return;

    direction = nextDirection;
    if (direction.x === 0 && direction.y === 0) return;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
        snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      updateScore();
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    running = false;
    clearInterval(loopId);
    overlayTitle.textContent = 'Game Over';
    overlayText.textContent = 'Your score: ' + score + '. Press Restart or R to play again.';
    startBtn.textContent = 'Play Again';
    showOverlay();
  }

  function showOverlay() {
    overlay.classList.remove('hidden');
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function startGame() {
    if (gameOver) {
      init();
    }
    running = true;
    paused = false;
    gameOver = false;
    hideOverlay();
    pauseBtn.textContent = 'Pause';
    clearInterval(loopId);
    loopId = setInterval(step, 150);
  }

  function togglePause() {
    if (!running || gameOver) return;
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    if (paused) {
      overlayTitle.textContent = 'Paused';
      overlayText.textContent = 'Press Space or Resume to continue.';
      startBtn.textContent = 'Resume';
      showOverlay();
    } else {
      hideOverlay();
    }
  }

  function restart() {
    clearInterval(loopId);
    init();
    startGame();
  }

  function handleKey(e) {
    const key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      if (!running && !gameOver) {
        startGame();
      } else {
        togglePause();
      }
      return;
    }
    if (key === 'r' || key === 'R') {
      e.preventDefault();
      restart();
      return;
    }
    if (!running || paused || gameOver) return;

    const dirs = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };

    if (dirs[key]) {
      e.preventDefault();
      const d = dirs[key];
      if (d.x === -direction.x && d.y === -direction.y) return;
      nextDirection = d;
    }
  }

  document.addEventListener('keydown', handleKey);
  startBtn.addEventListener('click', function () {
    if (paused && running) {
      togglePause();
    } else {
      startGame();
    }
  });
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);

  init();
})();
